        vm.stopPrank();

        vm.prank(relayer);
        vm.expectRevert("MC/exchange-rate-too-high");
        mainnetController.depositERC4626(address(susds), 5_000_000e18, 0);

        vm.startPrank(Ethereum.SPARK_PROXY);
