    function test_removeDelegatedSigner() external {
        address signer = makeAddr("signer");

        IEthenaMinterLike ethenaMinter = IEthenaMinterLike(ETHENA_MINTER);

        vm.prank(relayer);
        mainnetController.setDelegatedSigner(signer);

