        vm.prank(relayer);
        mainnetController.swapUSDCToUSDS(maxSwapAmount);

        assertEq(usds.balanceOf(address(almProxy)), maxSwapAmount * 1e12);

        ( Art,,,, ) = dss.vat.ilks(PSM_ILK);

