            lpShares += psm.shares(lpHandler.lps(i));
        }

        assertEq(lpShares, psm.totalShares());
    }

    function _checkInvariant_B() public view {
        assertApproxEqAbs(
            psm.totalAssets(),
            psm.convertToAssetValue(psm.totalShares()),
            4
        );
    }

