        usds.mint(user1, 100e18 - 1);

        vm.startPrank(user1);

        usds.approve(address(psm), 100e18);

        vm.expectRevert("SafeERC20/transfer-from-failed");
        psm.deposit(address(usds), user1, 100e18);

