            asset:          WBTC,
            ltv:            70_00,
            liqThreshold:   75_00,
            liqBonus:       7_00,
            debtCeiling:    0,
            liqProtocolFee: 10_00,
            eModeCategory:  0
        });

        return collateralUpdates;
