                optimalUsageRatio:             wethOldInterestRateStrategy.OPTIMAL_USAGE_RATIO(),
                optimalStableToTotalDebtRatio: wethOldInterestRateStrategy.OPTIMAL_STABLE_TO_TOTAL_DEBT_RATIO(),
