        _testCurveOnboarding({
            pool:                        CURVE_SUSDSUSDT,
            expectedDepositAmountToken0: 2_000_000e18,
            expectedSwapAmountToken0:    1_000_000e18,
            maxSlippage:                 0.9985e18,
