    function test_ETHEREUM_TBTCChanges() public onChain(ChainIdUtils.Ethereum()) {
        _testIRMChanges({
            asset:      Ethereum.TBTC,
            oldOptimal: 0.6e27,
            oldBase:    0,
            oldSlope1:  0.04e27,
            oldSlope2:  3e27,
            newOptimal: 0.8e27,
            newBase:    0,
            newSlope1:  0.01e27,
            newSlope2:  3e27
        });
    }

    function test_ETHEREUM_WBTCChanges() public onChain(ChainIdUtils.Ethereum()) {
