        // Onboard PT-syrupUSDC-28Aug2025/DAI
        IMetaMorpho(Ethereum.MORPHO_VAULT_DAI_1).submitCap(
            MarketParams({
                loanToken:       Ethereum.DAI,
                collateralToken: PT_SYRUP_USDC_28AUG2025,
