                collateralToken: PT_USDE_25SEP2025,
                oracle:          PT_USDE_25SEP2025_PRICE_FEED,
                irm:             Ethereum.MORPHO_DEFAULT_IRM,
                lltv:            0.915e18
            }),
            500_000_000e18
        );

        // Transfer USDS to destination
        IERC20(Ethereum.USDS).transfer(DESTINATION, TRANSFER_AMOUNT);
    }

}

