    // Expressed in ray.
    uint256 internal immutable _variableRateSlope1;

    // Slope of the variable interest curve when usage ratio > OPTIMAL_USAGE_RATIO.
    // Expressed in ray.
    uint256 internal immutable _variableRateSlope2;

